solution.Solution.cs:
using System.Globalization;
using System.Net;
using System.Net.Http;

public record Forecast(string City, double TempC, string Summary);

public interface IWeatherApi
{
    Task<Forecast> GetAsync(string city, CancellationToken ct = default);
}

public class WeatherService(IWeatherApi api, Func<DateTime> clock)
{
    private static readonly TimeSpan Fresh = TimeSpan.FromMinutes(10);
    private readonly Dictionary<string, (Forecast Forecast, DateTime At)> _cache = new(StringComparer.OrdinalIgnoreCase);

    public async Task<string> DescribeAsync(string city, CancellationToken ct = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(city);
        string key = city.Trim();
        if (_cache.TryGetValue(key, out var hit) && clock() - hit.At < Fresh) return Format(hit.Forecast);

        try
        {
            var forecast = await FetchWithRetryAsync(key, ct);
            _cache[key] = (forecast, clock());
            return Format(forecast);
        }
        catch (HttpRequestException) when (_cache.ContainsKey(key))
        {
            return Format(_cache[key].Forecast) + " (cached)";
        }
    }

    private async Task<Forecast> FetchWithRetryAsync(string city, CancellationToken ct)
    {
        for (int attempt = 1; ; attempt++)
        {
            try
            {
                return await api.GetAsync(city, ct);
            }
            catch (HttpRequestException e) when (attempt < 3 && IsTransient(e.StatusCode))
            {
                await Task.Delay(10 * attempt, ct);
            }
        }
    }

    private static bool IsTransient(HttpStatusCode? code) =>
        code is null || code == HttpStatusCode.TooManyRequests || (int)code >= 500;

    private static string Format(Forecast f) =>
        $"{f.City}: {f.TempC.ToString("F1", CultureInfo.InvariantCulture)} C, {f.Summary}";
}

unitTests:
static string Run(Task<string> t) => t.GetAwaiter().GetResult();

var now = new DateTime(2026, 3, 14, 9, 0, 0);
DateTime Clock() => now;

Test("describing and caching", () =>
{
    var api = new FakeApi();
    api.Results.Enqueue(new Forecast("Oslo", -3.26, "snow"));
    api.Results.Enqueue(new Forecast("Oslo", 1, "sleet"));
    var svc = new WeatherService(api, Clock);
    CheckEq(Run(svc.DescribeAsync(" oslo ")), "Oslo: -3.3 C, snow");
    CheckEq(Run(svc.DescribeAsync("OSLO")), "Oslo: -3.3 C, snow");
    CheckEq(api.Calls, 1);
    now = now.AddMinutes(11);
    CheckEq(Run(svc.DescribeAsync("Oslo")), "Oslo: 1.0 C, sleet");
    CheckEq(api.Calls, 2);
    CheckThrows<ArgumentException>(() => Run(svc.DescribeAsync("  ")));
    CheckEq(api.Calls, 2);
});

Test("retrying transient failures", () =>
{
    var api = new FakeApi();
    api.Errors.Enqueue(new HttpRequestException("busy", null, System.Net.HttpStatusCode.ServiceUnavailable));
    api.Errors.Enqueue(new HttpRequestException("no network"));
    api.Results.Enqueue(new Forecast("Rome", 18, "sunny"));
    var svc = new WeatherService(api, Clock);
    CheckEq(Run(svc.DescribeAsync("Rome")), "Rome: 18.0 C, sunny");
    CheckEq(api.Calls, 3);
});

Test("giving up", () =>
{
    var api = new FakeApi();
    for (int i = 0; i < 3; i++) api.Errors.Enqueue(new HttpRequestException("down", null, System.Net.HttpStatusCode.InternalServerError));
    var svc = new WeatherService(api, Clock);
    CheckThrows<HttpRequestException>(() => Run(svc.DescribeAsync("Lima")));
    CheckEq(api.Calls, 3);

    var notFound = new FakeApi();
    notFound.Errors.Enqueue(new HttpRequestException("nope", null, System.Net.HttpStatusCode.NotFound));
    CheckThrows<HttpRequestException>(() => Run(new WeatherService(notFound, Clock).DescribeAsync("Atlantis")));
    CheckEq(notFound.Calls, 1);
});

Test("falling back to an old result", () =>
{
    var api = new FakeApi();
    api.Results.Enqueue(new Forecast("Oslo", 2, "cloudy"));
    var svc = new WeatherService(api, Clock);
    Run(svc.DescribeAsync("Oslo"));
    now = now.AddHours(1);
    for (int i = 0; i < 3; i++) api.Errors.Enqueue(new HttpRequestException("timeout"));
    CheckEq(Run(svc.DescribeAsync("Oslo")), "Oslo: 2.0 C, cloudy (cached)");
});

