support.FakeApi.cs:
using System.Net.Http;

public class FakeApi : IWeatherApi
{
    public Queue<Exception> Errors { get; } = new();
    public Queue<Forecast> Results { get; } = new();
    public int Calls { get; private set; }

    public async Task<Forecast> GetAsync(string city, CancellationToken ct = default)
    {
        Calls++;
        await Task.Delay(1, ct);
        if (Errors.Count > 0) throw Errors.Dequeue();
        return Results.Dequeue();
    }
}
